sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Only run when ticket_status is Open or Closed
    if (!current.ticket_status ||
        (current.ticket_status != 'open' && current.ticket_status != 'closed')) {
        return;
    }

    // Ensure the maintenance ticket is linked to a workspace
    if (!current.workspace) {
        gs.info('WRM Maintenance BR: No workspace linked to maintenance ticket ' + current.number);
        return;
    }

    // Load the Workspace Options record
    var ws = new GlideRecord('x_1534869_wrm_workspace_options');
    if (!ws.get(current.workspace)) {
        gs.info('WRM Maintenance BR: Workspace record not found for sys_id ' + current.workspace);
        return;
    }

    var newStatus = '';

    // Requirement 1: Ticket OPEN → Workspace = Under maintenance
    if (current.ticket_status == 'open') {
        newStatus = 'under_maintenance'; // internal value from your instance
    }

    // Requirement 2: Ticket CLOSED → Workspace = maintenance ticket's workspace_status
    if (current.ticket_status == 'closed') {

        // workspace_status is already an internal value (available / decommissioned)
        newStatus = current.workspace_status;

        if (!newStatus) {
            gs.info('WRM Maintenance BR: workspace_status is empty on closed ticket ' + current.number);
            return;
        }
    }

    // Only update if the workspace status is actually changing
    if (ws.status != newStatus) {

        gs.info('WRM Maintenance BR: Updating workspace ' + ws.number +
            ' status from ' + ws.status + ' to ' + newStatus);

        ws.setValue('status', newStatus);

        // Requirement 3: Explicit save because this is another-table update
        ws.update();

        gs.info('WRM Maintenance BR: Final workspace status = ' + ws.status);
    }


})(current, previous);
